/* bluplay - a minimalistic terminal music player for BluOS streamers.
 *
 * Browses the player's local music library (folders/albums), manages the play queue and
 * controls playback over the BluOS HTTP API (port 11000). Plain C + POSIX libc: HTTP/1.1 over
 * sockets, a minimal XML scanner, termios + ANSI/VT100 escape sequences for the UI.
 *
 * Build:  make            (or: cc -O2 -o bluplay bluplay.c -lm)
 * Config: ~/.config/bluplay/config, BLUPLAY_* environment variables, command-line flags.
 *         Run "bluplay --help" for details. See README.md.
 *
 * SPDX-License-Identifier: MIT
 */
#define _GNU_SOURCE
#define BLUPLAY_VERSION "0.1.1"
#include <stdio.h>
