#include <sys/socket.h>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <sys/wait.h>

/* ---------------------------------------------------------------- utils */
typedef struct { char *p; size_t n, cap; } Buf;
static void *xrealloc(void *p, size_t n) { p = realloc(p, n ? n : 1); if (!p) { fputs("out of memory\n", stderr); exit(1); } return p; }
static void bgrow(Buf *b, size_t need) {
    if (b->n + need + 1 > b->cap) { size_t c = b->cap ? b->cap : 256; while (c < b->n + need + 1) c *= 2; b->p = xrealloc(b->p, c); b->cap = c; }
}
static void bcat(Buf *b, const char *s, size_t n) { bgrow(b, n); memcpy(b->p + b->n, s, n); b->n += n; b->p[b->n] = 0; }
static void bputs(Buf *b, const char *s) { bcat(b, s, strlen(s)); }
static void bputc(Buf *b, int c) { char ch = (char)c; bcat(b, &ch, 1); }
static void breset(Buf *b) { b->n = 0; if (b->p) b->p[0] = 0; }
static void bfree(Buf *b) { free(b->p); b->p = NULL; b->n = b->cap = 0; }
static void bprintf(Buf *b, const char *fmt, ...) {
    va_list ap; char tmp[512]; va_start(ap, fmt); int n = vsnprintf(tmp, sizeof tmp, fmt, ap); va_end(ap);
    if (n < 0) return;
    if ((size_t)n < sizeof tmp) { bcat(b, tmp, n); return; }
    bgrow(b, n); va_start(ap, fmt); vsnprintf(b->p + b->n, n + 1, fmt, ap); va_end(ap); b->n += n;
}
static char *xstrdup(const char *s) { size_t n = strlen(s); char *p = xrealloc(NULL, n + 1); memcpy(p, s, n + 1); return p; }
static char *xstrndup(const char *s, size_t n) { char *p = xrealloc(NULL, n + 1); memcpy(p, s, n); p[n] = 0; return p; }
static int isal(int c) { return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'); }
static int isdig(int c) { return c >= '0' && c <= '9'; }
static int isws(int c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v'; }

/* snprintf for display strings where truncation is intended */
static void xsnprintf(char *dst, size_t cap, const char *fmt, ...) __attribute__((format(printf, 3, 4)));
static void xsnprintf(char *dst, size_t cap, const char *fmt, ...) { va_list ap; va_start(ap, fmt); vsnprintf(dst, cap, fmt, ap); va_end(ap); }

static char ERR[300];
static void sanitize(char *s);
static int fail(const char *fmt, ...) { va_list ap; va_start(ap, fmt); vsnprintf(ERR, sizeof ERR, fmt, ap); va_end(ap); sanitize(ERR); return -1; }

static volatile sig_atomic_t got_sig, got_winch, force_redraw;
static int SIGFD[2] = { -1, -1 };   /* self-pipe: a signal always wakes poll() (no race between flag check and poll) */
static void sig_wake(void) { if (SIGFD[1] >= 0) { int e = errno; ssize_t r = write(SIGFD[1], "x", 1); (void)r; errno = e; } }
static int xpoll(struct pollfd *pf, nfds_t n, int tmo) {   /* like poll(); a wake-up from a signal gives -1/EINTR */
    struct pollfd t[8];
    if (SIGFD[0] < 0 || n > 7) return poll(pf, n, tmo);
    if (n) memcpy(t, pf, n * sizeof *pf);
    t[n].fd = SIGFD[0]; t[n].events = POLLIN; t[n].revents = 0;
    int r = poll(t, n + 1, tmo);
    if (r < 0) return r;
    if (n) memcpy(pf, t, n * sizeof *pf);
    if (t[n].revents) {
        char junk[64]; while (read(SIGFD[0], junk, sizeof junk) > 0) {}
        if (--r == 0) { errno = EINTR; return -1; }
    }
    return r;
}
static double mono(void) { struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9; }
static double wall(void) { struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts); return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9; }

/* UTF-8 */
static int u8dec(const char *s, const char *end, int *cp) {   /* -> bytes used (>=1); invalid -> U+FFFD, 1 byte */
    const unsigned char *p = (const unsigned char *)s; int n = (int)(end - s);
    if (n <= 0) { *cp = 0; return 0; }
    if (p[0] < 0x80) { *cp = p[0]; return 1; }
    if (p[0] >= 0xC2 && p[0] < 0xE0 && n >= 2 && (p[1] & 0xC0) == 0x80) { *cp = ((p[0] & 31) << 6) | (p[1] & 63); return 2; }
    if (p[0] >= 0xE0 && p[0] < 0xF0 && n >= 3 && (p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80) {
        int c = ((p[0] & 15) << 12) | ((p[1] & 63) << 6) | (p[2] & 63);
        if (c >= 0x800 && !(c >= 0xD800 && c < 0xE000)) { *cp = c; return 3; }
    }
    if (p[0] >= 0xF0 && p[0] < 0xF5 && n >= 4 && (p[1] & 0xC0) == 0x80 && (p[2] & 0xC0) == 0x80 && (p[3] & 0xC0) == 0x80) {
        int c = ((p[0] & 7) << 18) | ((p[1] & 63) << 12) | ((p[2] & 63) << 6) | (p[3] & 63);
        if (c >= 0x10000 && c < 0x110000) { *cp = c; return 4; }
    }
    *cp = 0xFFFD; return 1;
}
static int u8enc(int c, char *o) {   /* invalid code points (outside Unicode, surrogates) -> U+FFFD */
    if (c < 0 || c > 0x10FFFF || (c >= 0xD800 && c < 0xE000)) c = 0xFFFD;
    if (c < 0x80) { o[0] = (char)c; return 1; }
    if (c < 0x800) { o[0] = (char)(0xC0 | (c >> 6)); o[1] = (char)(0x80 | (c & 63)); return 2; }
    if (c < 0x10000) { o[0] = (char)(0xE0 | (c >> 12)); o[1] = (char)(0x80 | ((c >> 6) & 63)); o[2] = (char)(0x80 | (c & 63)); return 3; }
    o[0] = (char)(0xF0 | (c >> 18)); o[1] = (char)(0x80 | ((c >> 12) & 63)); o[2] = (char)(0x80 | ((c >> 6) & 63)); o[3] = (char)(0x80 | (c & 63)); return 4;
}
static void bput_cp(Buf *b, int c) { char t[4]; bcat(b, t, u8enc(c, t)); }
/* copy src to dst (cap bytes incl. NUL), cut at a character boundary */
static void cpy(char *dst, size_t cap, const char *src) {
    size_t n = strlen(src);
    if (n >= cap) { n = cap - 1; while (n > 0 && ((unsigned char)src[n] & 0xC0) == 0x80) n--; }
    memcpy(dst, src, n); dst[n] = 0;
}

