static void say(const char *fmt, ...) { va_list ap; va_start(ap, fmt); vsnprintf(msg, sizeof msg, fmt, ap); va_end(ap); msgt = wall(); }

/* ---- queue selection: range from anchor (qanchor) to cursor (qsel); qvis = select mode (key v) for terminals without Shift+arrows */
static int qanchor = -1, qvis, qgen;   /* qgen increments whenever the queue is replaced (modals check the selection is still valid) */
static void sel_clear(void) { qanchor = -1; qvis = 0; }
static void q_replaced(void) { qgen++; sel_clear(); }
static int sel_range(int *lo, int *hi) {   /* 0 = no selection */
    if (qanchor < 0) return 0;
    if (Q.n <= 0) { sel_clear(); return 0; }
    if (qanchor > Q.n - 1) qanchor = Q.n - 1;
    int s = qsel < 0 ? 0 : qsel > Q.n - 1 ? Q.n - 1 : qsel;
    *lo = qanchor < s ? qanchor : s; *hi = qanchor < s ? s : qanchor;
    return 1;
}

static int pos_now(void) {
    int n = S.secs;
    if ((!strcmp(S.state, "play") || !strcmp(S.state, "stream")) && st_rx != 0) {
        double e = mono() - st_rx; if (e < 0) e = 0;
        n = (int)(n + e); if (S.tot > 0 && n > S.tot) n = S.tot;
    }
    return n;
}
static void mmss(char *o, size_t cap, double sec) { int s = sec < 0 ? 0 : (int)sec; snprintf(o, cap, "%02d:%02d", s / 60, s % 60); }

/* ---- view (filter) */
static int *VIEW; static int nview, viewcap, view_ident;
static void build_view(void) {
    Level *L = &stack[nstack - 1]; Items *it = L->items;
    if (!L->flt[0]) { view_ident = 1; nview = it->n; return; }
    view_ident = 0; nview = 0;
    Buf f = {0}; lower_str(&f, L->flt);
    for (int i = 0; i < it->n; i++) {
        Buf t = {0}; lower_str(&t, Z(it->v[i].text));
        if (strstr(t.p ? t.p : "", f.p ? f.p : "")) {
            if (nview == viewcap) { viewcap = viewcap ? viewcap * 2 : 256; VIEW = xrealloc(VIEW, viewcap * sizeof(int)); }
            VIEW[nview++] = i;
        }
        bfree(&t);
    }
    bfree(&f);
}
static Item *vi(int i) { Level *L = &stack[nstack - 1]; return &L->items->v[view_ident ? i : VIEW[i]]; }

/* ---- drawing */
#define MAXH 300
static Buf rows[MAXH]; static char *prevrows[MAXH]; static int prevH, prevW;
static void rput(int y, const char *text, int w, int attr, int right) {
    if (y < 0 || y >= MAXH || w <= 0) return;
    Buf *r = &rows[y];
    if (attr) {
        bputs(r, "\033[");
        int first = 1;
        if (attr & A_BOLD) { bputs(r, "1"); first = 0; }
        if (attr & A_DIM) { bputs(r, first ? "2" : ";2"); first = 0; }
        if (attr & A_UL) { bputs(r, first ? "4" : ";4"); first = 0; }
        if (attr & A_REV) { bputs(r, first ? "7" : ";7"); first = 0; }
        if (attr >> 8) bprintf(r, "%s38;5;16;48;5;%d", first ? "" : ";", attr >> 8);
        bputc(r, 'm');
    }
    fit(r, text, w, right);
    if (attr) bputs(r, "\033[0m");
}
