    if (d) { struct dirent *e; while ((e = readdir(d))) { if (!strcmp(e->d_name, ".") || !strcmp(e->d_name, "..")) continue; char p[1400]; snprintf(p, sizeof p, "%s/%s", dir, e->d_name); unlink(p); } closedir(d); }
