      o = fopen(op.p, "wb");
      if (!o) { bfree(&op); goto out; }
      int ins = 0; static unsigned char cp[1 << 20];
      for (int i = 0; i < n; i++) {
          if (!memcmp(top[i].t, "moov", 4)) continue;
          if (!ins && memcmp(top[i].t, "ftyp", 4)) { if (fwrite(d, 1, len, o) != len) { bfree(&op); goto out; } ins = 1; }
          fseeko(f, top[i].s, SEEK_SET); unsigned long long left = top[i].e - top[i].s;
          while (left > 0) { size_t c = left < sizeof cp ? (size_t)left : sizeof cp; size_t r = fread(cp, 1, c, f); if (r == 0 || fwrite(cp, 1, r, o) != r) { bfree(&op); goto out; } left -= r; }
      }
